"""Grading suite for the cleared interchange epoch.

The reference clearance of the shipped epoch and the artifact digests of forty
nine mutated epochs are embedded below. None of it appears anywhere in the
agent environment. Every generalisation check materialises one mutated
register set into a scratch directory, runs the delivered program against it,
and compares every artifact that came out with the digest the reference engine
settled that same register set to.

The embedded reference is a zlib stream of one JSON object, written out in
hexadecimal, so that the expected artifacts do not have to sit in the source
as one enormous literal. Hexadecimal keeps the payload inside the alphabet 0
to 9 and a to f, so no word a reviewer greps the bundle for can turn up inside
it by accident. It is inspectable in one step:

    python3 -c "import json,re,zlib;
    src=open('test_output.py').read();
    blob=re.search(r'ORACLE_BLOB_HEX = .([0-9a-f]+).', src).group(1);
    print(json.dumps(json.loads(zlib.decompress(bytes.fromhex(blob))), indent=2)[:4000])"

The object carries the register column order, the base registers, the two
calibration blocks, the reference artifacts of the shipped epoch, and one
entry per mutated corpus holding the mutation that produces it and the digest
of every artifact it settles to.

Each check returns a bool and never raises: an exception inside a check aborts
the whole rewardkit run and leaves no score behind.
"""

import ast
import copy
import csv
import hashlib
import io
import json
import os
import pathlib
import shutil
import signal
import subprocess
import sys
import tempfile
import zlib

from rewardkit import criteria, criterion

ORACLE_BLOB_HEX = ""

BLOB = json.loads(zlib.decompress(bytes.fromhex(ORACLE_BLOB_HEX)).decode("utf-8"))
CSV_FIELDS = BLOB["csv_fields"]
BASE_REGISTERS = BLOB["base_registers"]
CALIBRATION = BLOB["calibration"]
SHIFTED_CALIBRATION = BLOB["shifted_calibration"]
READINGS = BLOB["readings"]
REFERENCE = BLOB["reference"]
REFERENCE_ARTIFACTS = REFERENCE["artifacts"]
REFERENCE_DIGESTS = REFERENCE["digests"]
VARIANTS = BLOB["variants"]

OUT_SUBDIR = "out"
PROGRAM_NAME = "clear_epoch.py"

# instruction.md promises the program finishes an epoch this size well inside
# 300 seconds, so 300 seconds is the budget each corpus run is given.
CORPUS_TIMEOUT_SEC = 300

# The seven properties the calibration slice pins, under the key names the
# epoch summary reports them with.
PROPERTY_NAMES = (
    "adjustment_order", "levy_basis", "grid_step_micros", "midpoint_rule",
    "void_reach", "cap_release_order", "fault_window_edge",
)

CLEARANCE_ARTIFACTS = (
    "summary.json", "reconciliation.json", "tap_ledger.json",
    "data_quality.json", "identity_register.json", "suspension_register.json",
    "cap_relief.json",
)
NETTING_ARTIFACTS = (
    "netting_summary.json", "netting_obligations.json", "netting_residual.json",
    "netting_positions.json", "netting_schedule.json",
)
ASSURANCE_ARTIFACTS = (
    "assurance_summary.json", "assurance_margins.json",
    "assurance_holdbacks.json", "assurance_order.json",
    "assurance_apportionment.json",
)
CYCLES_CSV = "netting_cycles.csv"
LADDER_CSV = "assurance_ladder.csv"

# Corpora grouped by the part of the contract each group stresses. A group
# passes only when every corpus in it settles to the reference digests.
IDENTITY_TARIFF_POLICY_CORPORA = (
    "identity_chain_deepened",
    "identity_cycle_widened",
    "identity_revocations_widened",
    "identity_events_after_every_tap",
    "tariff_all_live_at_once",
    "tariff_gap_widened",
    "epoch_boundary_open_open",
    "peak_window_shifted",
)
SUSPENSION_CAP_CORPORA = (
    "allowance_tightened_everywhere",
    "validation_floor_raised",
    "provisional_everywhere",
    "caps_tightened_everywhere",
    "float_ceiling_zeroed",
    "reversals_widened",
)
NETTING_ASSURANCE_CORPORA = (
    "interchange_share_zeroed",
    "netting_arithmetic_changed",
    "funding_ceiling_zeroed",
    "assurance_sigma_zeroed",
    "assurance_min_sample_above_sample",
    "one_operator_owns_everything",
    "zero_distance_everywhere",
)
CALIBRATION_CORPUS = BLOB["calibration_corpus"]
COVERAGE_CORPUS = "caps_tightened_everywhere"
ROW_ORDER_CORPUS = "register_rows_reversed"
HARDCODE_CORPUS = "epoch_narrowed"
ARBITRARY_CORPUS = "distances_doubled"

# The delivered program is agent authored code. The verifier runs as root so it
# can own /tests, so the program is dropped to an unprivileged uid and gid
# before it executes; otherwise it would inherit root and could read the
# embedded reference out of /tests or overwrite the published score. setpriv
# ships in util-linux, which the tests image installs.
_SETPRIV = ["setpriv", "--reuid=nobody", "--regid=nogroup", "--clear-groups"]

_CORPUS_CACHE = {}


# ---------------------------------------------------------------------------
# reading what the agent delivered
# ---------------------------------------------------------------------------

def _out(workspace):
    return pathlib.Path(workspace) / OUT_SUBDIR


def _script(workspace):
    return _out(workspace) / PROGRAM_NAME


def _read(workspace, name):
    """One delivered JSON artifact, or None when it is missing or unreadable."""
    try:
        with open(_out(workspace) / name, encoding="utf-8") as handle:
            return json.load(handle)
    except (OSError, ValueError):
        return None


def _read_text(workspace, name):
    try:
        return (_out(workspace) / name).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None


def _delivered_names(workspace):
    try:
        return sorted(p.name for p in _out(workspace).iterdir() if p.is_file())
    except OSError:
        return []


def _ledger_rows(workspace):
    payload = _read(workspace, "tap_ledger.json")
    if not isinstance(payload, dict):
        return []
    rows = payload.get("rows")
    return rows if isinstance(rows, list) else []


def _reference_rows(name, key="rows"):
    payload = REFERENCE_ARTIFACTS.get(name) or {}
    rows = payload.get(key)
    return rows if isinstance(rows, list) else []


def _by_key(rows, key):
    out = {}
    for row in rows:
        if isinstance(row, dict) and isinstance(row.get(key), str):
            out[row[key]] = row
    return out


def _fields_match(rows, reference, key, fields):
    """Every reference row is present and agrees on the named fields."""
    delivered = _by_key(rows, key)
    expected = _by_key(reference, key)
    if sorted(delivered) != sorted(expected):
        return False
    for identifier, want in expected.items():
        got = delivered[identifier]
        for field in fields:
            if field not in got or got[field] != want[field]:
                return False
    return True


def _rows_match(rows, reference, fields):
    """Row by row agreement on the named fields, for a list in a fixed order.

    The tap ledger and the identity resolutions are keyed by tap identifier,
    and a register may legitimately repeat one, so those two lists are compared
    position by position in the order the schema fixes rather than by key.
    """
    if not isinstance(rows, list) or len(rows) != len(reference):
        return False
    for got, want in zip(rows, reference):
        if not isinstance(got, dict):
            return False
        for field in fields:
            if field not in got or got[field] != want[field]:
                return False
    return True


# ---------------------------------------------------------------------------
# running the delivered program over a mutated register set
# ---------------------------------------------------------------------------

def _add_mode(path, bits):
    """Add permission bits to a path, keeping every bit it already carries.

    Permissions are only ever widened here. Setting an absolute mode would
    strip the execute bit off anything that needs one, and the arguments this
    is applied to include the interpreter itself.
    """
    try:
        current = os.stat(path).st_mode & 0o7777
    except OSError:
        return False
    if current | bits == current:
        return True
    try:
        os.chmod(path, current | bits)
    except OSError:
        return False
    return True


def _grant_program_read(script):
    """Let the unprivileged child open the program and walk down to it.

    A real agent writes its program through an editor, which renames a temp
    file into place and leaves the file at mode 0600 owned by uid 1000. Harbor
    hands the workspace to the verifier with those modes intact, so the
    unprivileged child could not open the program unless the verifier, which
    runs as root, opens it up first.
    """
    granted = _add_mode(script, 0o444)
    parent = pathlib.Path(script).parent
    while True:
        _add_mode(parent, 0o555)
        if parent.parent == parent:
            break
        parent = parent.parent
    return granted


def _grant_scratch_access(root):
    """Make a scratch tree readable and writable by the unprivileged child."""
    granted = _add_mode(root, 0o777)
    for current, directories, files in os.walk(root):
        for name in directories:
            _add_mode(os.path.join(current, name), 0o777)
        for name in files:
            _add_mode(os.path.join(current, name), 0o666)
    return granted


def _untrusted_command(command):
    """The command, wrapped so it runs as nobody and can still read its args."""
    for argument in command[1:]:
        path = pathlib.Path(argument)
        if not argument.startswith("/") or not path.exists():
            continue
        if path.is_dir():
            _grant_scratch_access(argument)
        else:
            _grant_program_read(argument)
    return _SETPRIV + command


def _reap(process):
    """Kill the whole process group so nothing the program spawned outlives it."""
    for killer in (signal.SIGTERM, signal.SIGKILL):
        try:
            os.killpg(os.getpgid(process.pid), killer)
        except (OSError, ProcessLookupError):
            break
        try:
            process.wait(timeout=5)
            break
        except subprocess.TimeoutExpired:
            continue
    try:
        process.wait(timeout=5)
    except subprocess.TimeoutExpired:
        pass


def _execute(command, timeout):
    """Run a command to completion, consuming both pipes. True when it exited 0."""
    try:
        process = subprocess.Popen(
            _untrusted_command(command),
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            start_new_session=True)
    except (OSError, ValueError):
        return False
    try:
        process.communicate(timeout=timeout)
    except subprocess.TimeoutExpired:
        _reap(process)
        return False
    except (OSError, ValueError):
        _reap(process)
        return False
    code = process.returncode
    if process.poll() is None:
        _reap(process)
    return code == 0


def _apply_mutations(base, operations):
    """A fresh register block with every mutation applied in order."""
    block = copy.deepcopy(base)
    for operation in operations:
        kind = operation["op"]
        table = operation.get("table")
        if kind == "reverse":
            block[table] = list(reversed(block[table]))
        elif kind == "replace_table":
            block[table] = copy.deepcopy(operation["rows"])
        elif kind == "add":
            block[table] = block[table] + copy.deepcopy(operation["rows"])
        elif kind == "drop":
            where = operation.get("where", {})
            block[table] = [row for row in block[table]
                            if not all(row.get(k) == v for k, v in where.items())]
        elif kind == "set_all":
            for row in block[table]:
                row.update(operation["set"])
        elif kind == "set":
            where = operation.get("where", {})
            for row in block[table]:
                if all(row.get(k) == v for k, v in where.items()):
                    row.update(operation["set"])
        elif kind == "scale":
            field = operation["field"]
            for row in block[table]:
                row[field] = row[field] * operation["factor"] // operation["divisor"]
    return block


def _write_corpus(block, data_dir, calibration):
    """Lay a register block out on disk the way a register directory looks."""
    os.makedirs(data_dir, exist_ok=True)
    for table, fields in CSV_FIELDS.items():
        buffer = io.StringIO()
        writer = csv.DictWriter(buffer, fieldnames=fields, lineterminator="\n")
        writer.writeheader()
        for row in block.get(table, []):
            writer.writerow({name: row.get(name, "") for name in fields})
        with open(os.path.join(data_dir, table + ".csv"), "w", encoding="utf-8") as handle:
            handle.write(buffer.getvalue())
    with open(os.path.join(data_dir, "exceptions.json"), "w", encoding="utf-8") as handle:
        handle.write(json.dumps({"exceptions": block.get("exceptions", [])},
                                indent=2, sort_keys=True) + "\n")
    with open(os.path.join(data_dir, "calibration_controls.json"), "w",
              encoding="utf-8") as handle:
        handle.write(json.dumps(calibration, indent=2, sort_keys=True) + "\n")


def _settle_corpus(workspace, name):
    """Run the delivered program over one corpus, once, and cache the result.

    Returns the directory the program wrote, or None when the program is
    missing, crashed, or ran past its budget.
    """
    if name in _CORPUS_CACHE:
        return _CORPUS_CACHE[name]
    _CORPUS_CACHE[name] = None
    script = _script(workspace)
    if not script.is_file():
        return None
    entry = VARIANTS.get(name)
    if entry is None:
        return None
    calibration = SHIFTED_CALIBRATION if name == CALIBRATION_CORPUS else CALIBRATION
    root = tempfile.mkdtemp(prefix="corpus-")
    data_dir = os.path.join(root, "registers")
    out_dir = os.path.join(root, "cleared")
    try:
        _write_corpus(_apply_mutations(BASE_REGISTERS, entry["mutations"]),
                      data_dir, calibration)
        os.makedirs(out_dir, exist_ok=True)
        _grant_scratch_access(root)
        ok = _execute([sys.executable, "-I", str(script), data_dir, out_dir],
                      CORPUS_TIMEOUT_SEC)
    except OSError:
        return None
    if not ok:
        return None
    _CORPUS_CACHE[name] = out_dir
    return out_dir


def _settle_base(workspace):
    """Run the delivered program over the shipped registers in a scratch tree."""
    key = "__base__"
    if key in _CORPUS_CACHE:
        return _CORPUS_CACHE[key]
    _CORPUS_CACHE[key] = None
    script = _script(workspace)
    if not script.is_file():
        return None
    root = tempfile.mkdtemp(prefix="plain-")
    data_dir = os.path.join(root, "registers")
    out_dir = os.path.join(root, "cleared")
    try:
        _write_corpus(_apply_mutations(BASE_REGISTERS, []), data_dir, CALIBRATION)
        os.makedirs(out_dir, exist_ok=True)
        _grant_scratch_access(root)
        ok = _execute([sys.executable, "-I", str(script), data_dir, out_dir],
                      CORPUS_TIMEOUT_SEC)
    except OSError:
        return None
    if not ok:
        return None
    _CORPUS_CACHE[key] = out_dir
    return out_dir


def _corpus_digests(out_dir):
    digests = {}
    try:
        names = sorted(os.listdir(out_dir))
    except OSError:
        return digests
    for name in names:
        path = os.path.join(out_dir, name)
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "rb") as handle:
                digests[name] = hashlib.sha256(handle.read()).hexdigest()
        except OSError:
            continue
    return digests


def _corpus_matches(workspace, name):
    """Every artifact the corpus settles to is byte identical to the reference."""
    out_dir = _settle_corpus(workspace, name)
    if out_dir is None:
        return False
    entry = VARIANTS.get(name) or {}
    return _corpus_digests(out_dir) == entry.get("digests")


def _corpus_json(workspace, name, artifact):
    out_dir = _settle_corpus(workspace, name)
    if out_dir is None:
        return None
    try:
        with open(os.path.join(out_dir, artifact), encoding="utf-8") as handle:
            return json.load(handle)
    except (OSError, ValueError):
        return None


def _group_passes(workspace, names):
    for name in names:
        if not _corpus_matches(workspace, name):
            return False
    return True


# ---------------------------------------------------------------------------
# independent recomputation, so the suite does not only compare digests
# ---------------------------------------------------------------------------

def _lower_middle(values):
    """Median taking the lower of the two middle values of an even sample."""
    ordered = sorted(values)
    size = len(ordered)
    if size == 0:
        return 0
    half, odd = divmod(size, 2)
    return ordered[half] if odd else ordered[half - 1]


def _largest_remainder(total, weights):
    """Apportion total across the keys of weights by the largest remainder."""
    keys = sorted(weights)
    weight_total = sum(weights[key] for key in keys)
    shares = dict((key, 0) for key in keys)
    if not keys:
        return shares
    if weight_total <= 0:
        shares[keys[0]] = total
        return shares
    pending = []
    assigned = 0
    for key in keys:
        exact = total * weights[key]
        whole = exact // weight_total
        shares[key] = whole
        assigned += whole
        pending.append((exact - whole * weight_total, key))
    pending.sort(key=lambda item: (-item[0], item[1]))
    cursor = 0
    while assigned < total and pending:
        shares[pending[cursor % len(pending)][1]] += 1
        assigned += 1
        cursor += 1
    return shares


def _first_cycle(edges):
    """The first simple cycle of a directed graph in canonical cycle order."""
    nodes = sorted(set([payer for payer, _ in edges] + [payee for _, payee in edges]))
    forward = dict((node, []) for node in nodes)
    for payer, payee in sorted(edges):
        forward[payer].append(payee)
    winner = None
    for origin in nodes:
        frontier = [(origin, (origin,))]
        while frontier:
            node, path = frontier.pop()
            for nxt in forward[node]:
                if nxt == origin:
                    candidate = (len(path), path)
                    if winner is None or candidate < winner:
                        winner = candidate
                elif nxt > origin and nxt not in path:
                    if winner is not None and len(path) + 1 > winner[0]:
                        continue
                    frontier.append((nxt, path + (nxt,)))
    return list(winner[1]) if winner else None


def _cancel_cycles(gross):
    """Cancel cycles out of a gross obligation map until none is left."""
    residual = dict(gross)
    cancelled = []
    while True:
        live = set(key for key, amount in residual.items() if amount > 0)
        if not live:
            break
        cycle = _first_cycle(live)
        if cycle is None:
            break
        pairs = [(cycle[i], cycle[(i + 1) % len(cycle)]) for i in range(len(cycle))]
        amount = min(residual[pair] for pair in pairs)
        for pair in pairs:
            residual[pair] -= amount
            if residual[pair] == 0:
                del residual[pair]
        cancelled.append((list(cycle), amount))
    return residual, cancelled


def _gate_floor(gate_id):
    for row in BASE_REGISTERS["gates"]:
        if row["gate_id"] == gate_id:
            return row["floor_fare_micros"]
    return None


# ---------------------------------------------------------------------------
# delivery and form
# ---------------------------------------------------------------------------

def program_delivered(workspace: pathlib.Path) -> bool:
    script = _script(workspace)
    try:
        source = script.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return False
    if not source.strip():
        return False
    try:
        ast.parse(source)
    except SyntaxError:
        return False
    return True


def fixed_artifacts_present(workspace: pathlib.Path) -> bool:
    for name in CLEARANCE_ARTIFACTS + NETTING_ARTIFACTS + ASSURANCE_ARTIFACTS:
        payload = _read(workspace, name)
        if not isinstance(payload, dict) or not payload:
            return False
    for name in (CYCLES_CSV, LADDER_CSV):
        text = _read_text(workspace, name)
        if not text or not text.endswith("\n"):
            return False
    return True


@criterion(description="the delivered program clears an arbitrary register set given two directory arguments")
def program_clears_an_arbitrary_register_set(workspace: pathlib.Path) -> bool:
    return _corpus_matches(workspace, ARBITRARY_CORPUS)


def serialization_form(workspace: pathlib.Path) -> bool:
    names = _delivered_names(workspace)
    checked = 0
    for name in names:
        if name == PROGRAM_NAME:
            continue
        text = _read_text(workspace, name)
        if text is None:
            return False
        if not text.endswith("\n"):
            return False
        if name.endswith(".json"):
            try:
                payload = json.loads(text)
            except ValueError:
                return False
            if text != json.dumps(payload, indent=2, sort_keys=True) + "\n":
                return False
            checked += 1
        elif name.endswith(".csv"):
            if text.endswith("\n\n"):
                return False
            checked += 1
        else:
            return False
    return checked >= 10


# ---------------------------------------------------------------------------
# the cleared account
# ---------------------------------------------------------------------------

@criterion(description="the epoch summary carries the reference figures for the shipped epoch")
def summary_matches_reference(workspace: pathlib.Path) -> bool:
    delivered = _read(workspace, "summary.json")
    want = REFERENCE_ARTIFACTS.get("summary.json")
    if not isinstance(delivered, dict) or not isinstance(want, dict):
        return False
    # resolved_parameters belongs to the recovery check, so it is left out here
    # and nothing is paid for it twice.
    keys = sorted(set(want) - set(["resolved_parameters"]))
    if sorted(set(delivered) - set(["resolved_parameters"])) != keys:
        return False
    for key in keys:
        if delivered[key] != want[key]:
            return False
    return True


@criterion(description="the reported platform properties are the ones the calibration figures admit")
def recovered_properties_match_calibration(workspace: pathlib.Path) -> bool:
    delivered = _read(workspace, "summary.json")
    want = (REFERENCE_ARTIFACTS.get("summary.json") or {}).get("resolved_parameters")
    if not isinstance(delivered, dict) or not isinstance(want, dict):
        return False
    got = delivered.get("resolved_parameters")
    if not isinstance(got, dict):
        return False
    if sorted(got) != sorted(PROPERTY_NAMES):
        return False
    legal = CALIBRATION["legal_values"]
    for name in PROPERTY_NAMES:
        value = got[name]
        candidates = legal[name]
        if name == "adjustment_order":
            if list(value) not in [list(c) for c in candidates]:
                return False
        elif value not in candidates:
            return False
        if value != want[name]:
            return False
    return True


@criterion(description="every ledger row carries the unit fare the rate rules settle it on")
def unit_fares_match_reference(workspace: pathlib.Path) -> bool:
    return _rows_match(_ledger_rows(workspace), _reference_rows("tap_ledger.json"),
                       ("tap_id", "unit_fare_micros",
                        "gross_before_adjustments_micros",
                        "governing_table_id", "peak"))


@criterion(description="every ledger row carries the disposition and the withdrawal reason the rules give it")
def dispositions_and_reasons_match_reference(workspace: pathlib.Path) -> bool:
    return _rows_match(_ledger_rows(workspace), _reference_rows("tap_ledger.json"),
                       ("tap_id", "disposition", "withdrawal_reason",
                        "exception_id"))


@criterion(description="every conservation identity is present, in order, and closes at zero")
def conservation_residuals_zero(workspace: pathlib.Path) -> bool:
    delivered = _read(workspace, "reconciliation.json")
    want = REFERENCE_ARTIFACTS.get("reconciliation.json")
    if not isinstance(delivered, dict) or not isinstance(want, dict):
        return False
    rows = delivered.get("identities")
    expected = want.get("identities")
    if not isinstance(rows, list) or len(rows) != len(expected):
        return False
    for got, reference in zip(rows, expected):
        if not isinstance(got, dict):
            return False
        if got.get("identity") != reference["identity"]:
            return False
        if got.get("left") != reference["left"] or got.get("right") != reference["right"]:
            return False
        if got.get("residual") != 0:
            return False
    return delivered.get("residual_total") == 0


def identity_resolution_matches_reference(workspace: pathlib.Path) -> bool:
    delivered = _read(workspace, "identity_register.json")
    want = REFERENCE_ARTIFACTS.get("identity_register.json")
    if not isinstance(delivered, dict) or not isinstance(want, dict):
        return False
    return _rows_match(delivered.get("resolutions") or [],
                       want.get("resolutions") or [],
                       ("tap_id", "token_ref", "canonical_token", "outcome",
                        "chain"))


def home_and_cross_operator_resolution(workspace: pathlib.Path) -> bool:
    return _rows_match(_ledger_rows(workspace), _reference_rows("tap_ledger.json"),
                       ("tap_id", "home_operator_id", "cross_operator",
                        "operator_id", "zone_id", "canonical_token"))


def suspension_fixpoint_matches_reference(workspace: pathlib.Path) -> bool:
    delivered = _read(workspace, "suspension_register.json")
    want = REFERENCE_ARTIFACTS.get("suspension_register.json")
    if not isinstance(delivered, dict) or not isinstance(want, dict):
        return False
    if delivered.get("iterations") != want.get("iterations"):
        return False
