def ledger_order_and_running_total(workspace: pathlib.Path) -> bool:
    rows = _ledger_rows(workspace)
    reference = _reference_rows("tap_ledger.json")
    if not rows or len(rows) != len(reference):
        return False
    order = []
    running = 0
    total = 0
    for row in rows:
        if not isinstance(row, dict):
            return False
        instant = row.get("tapped_at")
        tap_id = row.get("tap_id")
        if not isinstance(instant, str) or not isinstance(tap_id, str):
            return False
        order.append((instant, tap_id))
        value = row.get("running_charge_micros")
        if not isinstance(value, int) or isinstance(value, bool) or value < running:
            return False
        running = value
        if row.get("disposition") == "priced":
            fare = row.get("unit_fare_micros")
            if not isinstance(fare, int) or isinstance(fare, bool):
                return False
            total += fare
        if value != total:
            return False
    if order != sorted(order):
        return False
    payload = _read(workspace, "tap_ledger.json") or {}
    want = REFERENCE_ARTIFACTS.get("tap_ledger.json") or {}
    return (payload.get("charge_micros") == want.get("charge_micros")
            and payload.get("row_count") == want.get("row_count")
            and running == want.get("charge_micros"))


