@criterion(description="every margin is the truncated per distance unit quotient and is not placed on the grid")
def assurance_margins_truncate_not_place(workspace: pathlib.Path) -> bool:
    margins = _read(workspace, "assurance_margins.json")
    if not isinstance(margins, dict):
        return False
    rows = margins.get("rows")
    if not isinstance(rows, list) or not rows:
        return False
    priced = {}
    for row in _reference_rows("tap_ledger.json"):
        if row["disposition"] == "priced" and row["distance_units"] > 0:
            priced[row["tap_id"]] = row
    if sorted(r.get("tap_id") for r in rows) != sorted(priced):
        return False
    for row in rows:
        reference = priced.get(row.get("tap_id"))
        if reference is None:
            return False
        floor = _gate_floor(reference["gate_id"])
        if floor is None:
            return False
        want = (reference["unit_fare_micros"] - floor) // reference["distance_units"]
        if row.get("margin") != want:
            return False
        if row.get("unit_fare_micros") != reference["unit_fare_micros"]:
            return False
        if row.get("floor_fare_micros") != floor:
            return False
        if row.get("distance_units") != reference["distance_units"]:
            return False
    return margins.get("row_count") == len(priced)


@criterion(description="the holdback threshold is the sigma multiple of the median absolute deviation about the median")
def assurance_holdback_threshold_uses_mad(workspace: pathlib.Path) -> bool:
    margins = _read(workspace, "assurance_margins.json")
    summary = _read(workspace, "assurance_summary.json")
    holdbacks = _read(workspace, "assurance_holdbacks.json")
    if not isinstance(margins, dict) or not isinstance(summary, dict):
        return False
    if not isinstance(holdbacks, dict):
        return False
    rows = margins.get("rows")
    if not isinstance(rows, list) or not rows:
        return False
    values = []
    for row in rows:
        if not isinstance(row, dict):
            return False
        value = row.get("margin")
        if not isinstance(value, int) or isinstance(value, bool):
            return False
        values.append(value)
    policy = BASE_REGISTERS["assurance_policy"][0]
    median = _lower_middle(values)
    deviations = [abs(value - median) for value in values]
    mad = _lower_middle(deviations)
    threshold = policy["assurance_sigma"] * mad
    small = len(values) <= policy["min_sample"]
    if summary.get("median_margin") != median or summary.get("mad") != mad:
        return False
    if summary.get("threshold") != threshold:
        return False
    held = []
    for row in rows:
        deviation = abs(row["margin"] - median)
        if row.get("deviation") != deviation:
            return False
        expected = (not small) and deviation > threshold
        if row.get("held_back") is not expected:
            return False
        if expected:
            held.append(row["tap_id"])
    if sorted(r.get("tap_id") for r in holdbacks.get("rows") or []) != sorted(held):
        return False
    return (summary.get("held_back_count") == len(held)
            and summary.get("retained_count") == len(values) - len(held)
            and summary.get("sample_size") == len(values))


@criterion(description="the distance apportionment is the largest remainder split of the retained distance")
def assurance_apportionment_largest_remainder(workspace: pathlib.Path) -> bool:
    margins = _read(workspace, "assurance_margins.json")
    apportionment = _read(workspace, "assurance_apportionment.json")
    summary = _read(workspace, "assurance_summary.json")
    if not isinstance(margins, dict) or not isinstance(apportionment, dict):
        return False
    if not isinstance(summary, dict):
        return False
    rows = margins.get("rows")
    if not isinstance(rows, list):
        return False
    retained = [row for row in rows if isinstance(row, dict) and not row.get("held_back")]
    weights = {}
    distance = 0
    pool = 0
    for row in retained:
        rider = row.get("rider_class")
        margin = row.get("margin")
        units = row.get("distance_units")
        if not isinstance(rider, str):
            return False
        if not isinstance(margin, int) or isinstance(margin, bool):
            return False
        if not isinstance(units, int) or isinstance(units, bool):
            return False
        weights[rider] = weights.get(rider, 0) + margin
        distance += units
        pool += margin
    shares = _largest_remainder(distance, weights)
    rebuilt = []
    for rider in sorted(shares):
        rebuilt.append({"rider_class": rider,
                        "retained_margin_micros": weights[rider],
                        "share_units": shares[rider]})
    if apportionment.get("shares") != rebuilt:
        return False
    if apportionment.get("retained_distance_units") != distance:
        return False
    if apportionment.get("share_total_units") != sum(shares.values()):
        return False
    if sum(shares.values()) != distance:
        return False
    return summary.get("pool_micros") == pool


def assurance_order_and_digest(workspace: pathlib.Path) -> bool:
    margins = _read(workspace, "assurance_margins.json")
    order = _read(workspace, "assurance_order.json")
    summary = _read(workspace, "assurance_summary.json")
    if not isinstance(margins, dict) or not isinstance(order, dict):
        return False
    if not isinstance(summary, dict):
        return False
    rows = margins.get("rows")
    if not isinstance(rows, list):
        return False
    retained = []
    for row in rows:
        if not isinstance(row, dict):
            return False
        if not row.get("held_back"):
            retained.append((row.get("margin"), row.get("tap_id")))
    retained.sort()
    if order.get("tap_ids") != [tap_id for _, tap_id in retained]:
        return False
    if order.get("margins") != [margin for margin, _ in retained]:
        return False
    policy = BASE_REGISTERS["assurance_policy"][0]
    digest = 0
    for margin, _ in retained:
        if not isinstance(margin, int) or isinstance(margin, bool):
            return False
        digest = (digest * policy["assurance_multiplier"] + margin) % policy["assurance_modulus"]
    return (order.get("digest") == digest
            and summary.get("assurance_digest") == digest)


def assurance_ladder_rendering(workspace: pathlib.Path) -> bool:
    text = _read_text(workspace, LADDER_CSV)
    margins = _read(workspace, "assurance_margins.json")
    apportionment = _read(workspace, "assurance_apportionment.json")
    if text is None or not isinstance(margins, dict):
        return False
    if not isinstance(apportionment, dict):
        return False
    rows = margins.get("rows")
    if not isinstance(rows, list):
        return False
    shares = {}
    for share in apportionment.get("shares") or []:
        if isinstance(share, dict):
            shares[share.get("rider_class")] = share.get("share_units")
    classes = sorted(set(row.get("rider_class") for row in rows
                         if isinstance(row, dict)))
    expected = ["rider_class,retained_count,held_back_count,margin_total,share_units"]
    for rider in classes:
        group = [row for row in rows if row.get("rider_class") == rider]
        retained = [row for row in group if not row.get("held_back")]
        expected.append("%s,%d,%d,%d,%d" % (
            rider, len(retained), len(group) - len(retained),
            sum(row["margin"] for row in retained), shares.get(rider, 0)))
    return text == "\n".join(expected) + "\n"


