@criterion(description="the program recovers the different reading a shifted calibration slice admits")
def recovers_a_different_reading_from_shifted_calibration(workspace: pathlib.Path) -> bool:
    summary = _corpus_json(workspace, CALIBRATION_CORPUS, "summary.json")
    if not isinstance(summary, dict):
        return False
    got = summary.get("resolved_parameters")
    shifted = READINGS.get("shifted")
    base = READINGS.get("base")
    if not isinstance(got, dict) or shifted is None:
        return False
    if sorted(got) != sorted(PROPERTY_NAMES):
        return False
    for name in PROPERTY_NAMES:
        want = shifted[name]
        value = got[name]
        if name == "adjustment_order":
            if list(value) != list(want):
                return False
        elif value != want:
            return False
    return not (base is not None and got == base)


