ALL_HELD_OUT_CORPORA = (IDENTITY_TARIFF_POLICY_CORPORA
                        + SUSPENSION_CAP_CORPORA
                        + NETTING_ASSURANCE_CORPORA)


def _family_matches_across_corpora(workspace, selector):
    """One artifact family, byte identical to the reference, on every held out corpus.

    `selector` is a tuple of artifact names or a predicate over a name, so a
    family can be named outright or matched by prefix. `_settle_corpus` caches
    each corpus, so the whole held out tier costs one run per corpus.
    """
    if callable(selector):
        wanted = selector
    else:
        names = frozenset(selector)
        def wanted(name):
            return name in names
    for corpus in ALL_HELD_OUT_CORPORA:
        out_dir = _settle_corpus(workspace, corpus)
        if out_dir is None:
            return False
        reference = (VARIANTS.get(corpus) or {}).get("digests")
        if not reference:
            return False
        produced = _corpus_digests(out_dir)
        for name in sorted(set(reference) | set(produced)):
            if wanted(name) and reference.get(name) != produced.get(name):
                return False
    return True


def _is_partition_report(name):
    return name.startswith("operator_") or name.startswith("zone_")


def _is_netting_artifact(name):
    return name.startswith("netting_")


@criterion(description="the tap ledger carries the reference rows on every held out register set")
def held_out_tap_ledger_matches_reference(workspace: pathlib.Path) -> bool:
    return _family_matches_across_corpora(workspace, ("tap_ledger.json",))


