@criterion(description="the program and every epoch level artifact are delivered in the byte form the shipped example demonstrates")
def program_and_artifacts_delivered_in_shipped_form(workspace: pathlib.Path) -> bool:
    return (program_delivered(workspace)
            and fixed_artifacts_present(workspace)
            and serialization_form(workspace))


@criterion(description="the ledger, quality register, cap relief and partition reports of the shipped epoch match the reference")
def clearance_secondary_matches_reference(workspace: pathlib.Path) -> bool:
    return (cap_relief_and_curtailment_match_reference(workspace)
            and home_and_cross_operator_resolution(workspace)
            and ledger_order_and_running_total(workspace)
            and quality_register_matches_reference(workspace)
            and partition_membership_derived(workspace)
            and partition_reports_match_reference(workspace))


@criterion(description="the identity resolution, suspension fixpoint and coverage obligation of the shipped epoch match the reference")
def identity_and_suspension_secondary_matches_reference(workspace: pathlib.Path) -> bool:
    return (identity_resolution_matches_reference(workspace)
            and suspension_fixpoint_matches_reference(workspace)
            and coverage_obligation_holds(workspace))


@criterion(description="the per operator positions, funding schedule and netting digest of the shipped epoch match the reference")
def netting_secondary_matches_reference(workspace: pathlib.Path) -> bool:
    return (netting_positions_and_schedule_match_reference(workspace)
            and netting_digest_matches_funding_order(workspace))


@criterion(description="the assurance order, digest and ladder rendering of the shipped epoch match the reference")
def assurance_secondary_matches_reference(workspace: pathlib.Path) -> bool:
    return (assurance_order_and_digest(workspace)
            and assurance_ladder_rendering(workspace))


# ---------------------------------------------------------------------------
# registrations
#
# The core outcome rides on the held out tier (weight 5): generalisation to a
# register set the agent never saw is what this task is for. Every artifact
# family below has a held out counterpart that grades the same property on
# twenty one unseen register sets, so the shipped epoch is the one instance the
# agent did see and matching it is a sanity property rather than the outcome:
# those checks carry weight 1. Parameter recovery stays at weight 5, because it
# has no held out counterpart and is the task's own central derivation.
# ---------------------------------------------------------------------------

criteria.held_out_tap_ledger_matches_reference(weight=5)
criteria.held_out_quality_register_matches_reference(weight=5)
criteria.held_out_summary_matches_reference(weight=5)
criteria.held_out_reconciliation_matches_reference(weight=5)
criteria.held_out_cap_relief_matches_reference(weight=5)
criteria.held_out_partition_reports_match_reference(weight=5)
criteria.held_out_assurance_margins_match_reference(weight=5)
criteria.held_out_assurance_digest_matches_reference(weight=5)
criteria.held_out_identity_and_suspension_match_reference(weight=5)
criteria.held_out_netting_matches_reference(weight=5)

criteria.recovered_properties_match_calibration(weight=5)
criteria.recovers_a_different_reading_from_shifted_calibration(weight=5)

criteria.summary_matches_reference(weight=1)
criteria.unit_fares_match_reference(weight=1)
criteria.dispositions_and_reasons_match_reference(weight=1)
criteria.conservation_residuals_zero(weight=1)
criteria.netting_obligations_match_reference(weight=1)
criteria.netting_cycle_cancellation_matches_reference(weight=1)
criteria.netting_residual_is_what_cancellation_yields(weight=1)
criteria.assurance_margins_truncate_not_place(weight=1)
criteria.assurance_holdback_threshold_uses_mad(weight=1)
criteria.assurance_apportionment_largest_remainder(weight=1)

criteria.program_and_artifacts_delivered_in_shipped_form(weight=1)
